(function(root){
'use strict';
function minutes(t){var p=t.split(':');return Number(p[0])*60+Number(p[1]);}
function key(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function midnight(d){return new Date(d.getFullYear(),d.getMonth(),d.getDate());}
function duration(s){return minutes(s.end)-minutes(s.start)-(s.paidLunch?0:minutes(s.lunchEnd)-minutes(s.lunchStart));}
function isWork(d,s){var value=s.overrides&&s.overrides[key(d)];return value==='rest'?false:value==='work'?true:s.days.indexOf(d.getDay())>=0;}
function elapsed(d,s){if(!isWork(d,s))return 0;var m=d.getHours()*60+d.getMinutes()+d.getSeconds()/60;var n=Math.max(0,Math.min(m,minutes(s.end))-minutes(s.start));if(!s.paidLunch)n-=Math.max(0,Math.min(m,minutes(s.lunchEnd))-minutes(s.lunchStart));return Math.max(0,Math.min(duration(s),n));}
function monthWorkdays(d,s){if(!s.calendarWorkdays)return s.workdays;var count=0;for(var i=1;i<=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();i++)if(s.days.indexOf(new Date(d.getFullYear(),d.getMonth(),i).getDay())>=0)count++;return Math.max(1,count);}
function legacySnapshot(now,s){if(s.mode==='all')return calendarSnapshot(now,s);var day=s.salary/monthWorkdays(now,s),rate=day/duration(s),today=elapsed(now,s)*rate,origin=midnight(new Date(s.since+'T00:00:00')),cursor=midnight(origin),end=midnight(now),gross=0,month='',daily=day;while(cursor<end){var currentMonth=cursor.getFullYear()+'-'+cursor.getMonth();if(month!==currentMonth){daily=s.salary/monthWorkdays(cursor,s);month=currentMonth;}if(isWork(cursor,s))gross+=daily;cursor.setDate(cursor.getDate()+1);}gross=now<origin?0:gross+today;return{today:today,daily:day,hourly:rate*60,progress:elapsed(now,s)/duration(s),total:s.initial+gross*s.percent/100,fund:today*s.percent/100};}
function dailyTarget(d,s){return s.salary/new Date(d.getFullYear(),d.getMonth()+1,0).getDate();}
function snapshot(now,s){if(s.dailyBasis==='legacy')return legacySnapshot(now,s);if(s.mode==='all')return calendarSnapshot(now,s);var day=dailyTarget(now,s),paid=duration(s),progress=elapsed(now,s)/paid,today=day*progress,origin=midnight(new Date(s.since+'T00:00:00')),cursor=midnight(origin),end=midnight(now),gross=0;while(cursor<end){if(isWork(cursor,s))gross+=dailyTarget(cursor,s);cursor.setDate(cursor.getDate()+1);}gross=now<origin?0:gross+today;return{today:today,daily:day,hourly:day/paid*60,progress:progress,total:s.initial+gross*s.percent/100,fund:today*s.percent/100};}
function calendarSnapshot(now,s){var days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(),daily=s.salary/days,seconds=now.getHours()*3600+now.getMinutes()*60+now.getSeconds(),today=daily*seconds/86400,cursor=midnight(new Date(s.since+'T00:00:00')),end=midnight(now),gross=0;while(cursor<end){gross+=s.salary/new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate();cursor.setDate(cursor.getDate()+1);}if(now>=new Date(s.since+'T00:00:00'))gross+=today;return{today:today,daily:daily,hourly:daily/24,progress:seconds/86400,total:s.initial+gross*s.percent/100,fund:today*s.percent/100};}
function allocate(wishes,total){var spent=wishes.reduce(function(sum,w){return sum+(w.bought?w.price:0);},0),left=Math.max(0,total-spent);return wishes.map(function(w){if(w.bought)return{amount:w.price,ready:true};var amount=Math.max(0,Math.min(w.price,left));left=Math.max(0,left-w.price);return{amount:amount,ready:amount>=w.price};});}
function balance(now,s,checkpoint){var v=snapshot(now,s);if(checkpoint)v.total=Math.max(0,checkpoint.amount+(v.total-checkpoint.raw));return v;}
function anchorOptions(wishes){return wishes.filter(function(w){return !w.bought;}).map(function(w){return {id:'wish:'+w.id,name:w.name};}).concat([{id:'coffee',name:'一杯喜欢的咖啡'},{id:'earbuds',name:'AirPods Pro'},{id:'phone',name:'iPhone Duo'}]);}
function anchor(wishes,total,salary,selection){var allocated=allocate(wishes,total),index=wishes.findIndex(function(w){return !w.bought;}),w,amount,defaults={coffee:{name:'一杯喜欢的咖啡',price:20,kind:'coffee'},earbuds:{name:'AirPods Pro',price:1388,kind:'earbuds'},phone:{name:'iPhone Duo',price:14999,kind:'phone'}};if(selection&&selection.indexOf('wish:')===0){var selected=wishes.findIndex(function(item){return !item.bought&&'wish:'+item.id===selection;});if(selected>=0)index=selected;}if(defaults[selection])index=-1;if(index>=0){w=wishes[index];amount=allocated[index].amount;}else{w=defaults[selection]||defaults[salary>=20000?'phone':salary<3000?'coffee':'earbuds'];amount=Math.max(0,total-wishes.reduce(function(sum,item){return sum+(item.bought?item.price:0);},0));}var kind=w.kind||(/phone|手机/i.test(w.name)?'phone':/airpods|耳机/i.test(w.name)?'earbuds':/咖啡|奶茶/.test(w.name)?'coffee':'gift');return{name:w.name,id:index>=0?'wish:'+w.id:w.kind,kind:kind,progress:Math.max(0,Math.min(1,amount/w.price)),own:index>=0};}
root.WNF={dailyTarget:dailyTarget,anchorOptions:anchorOptions,anchor:anchor,balance:balance,isWork:isWork,minutes:minutes,key:key,midnight:midnight,duration:duration,elapsed:elapsed,snapshot:snapshot,allocate:allocate};
})(typeof window==='undefined'?globalThis:window);
